/* WIMORO — auth module */

'use strict';

/* ===================== Créer un marché ===================== */
const COMM_PROPS=[{id:'pp-psg',q:_t("Le PSG sera-t-il champion de France 2027 ?"),cat:'Football',by:'karim',for:38,against:9,need:50},{id:'pp-jeu',q:_t("Un jeu vidéo dépassera-t-il 50 millions de ventes en 2027 ?"),cat:'Culture',by:'tomtom',for:21,against:6,need:50},{id:'pp-sol',q:_t("Le Solana dépassera-t-il 300 $ avant juin 2027 ?"),cat:'Crypto',by:'maxou',for:44,against:12,need:50}];
const slugify=s=>norm(s).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,28);
const shortOf=q=>{let s=q.replace(/\s*\?$/,'');if(s.length>34){s=s.slice(0,34);s=s.slice(0,s.lastIndexOf(' '))+'…';}return s;};
const dateFr=(d,t)=>{const x=new Date(d+'T'+(t||'21:00'));return isNaN(x)?'':_t('{0} à {1}',[fmtDay(x),hTxt(t||'21:00')]);};
function crChecks(dr){const q=dr.q.trim(),d=new Date(dr.date+'T'+(dr.time||'21:00'));return [{ok:q.length>=15,l:_t("Une question d’au moins 15 caractères")},{ok:/\?$/.test(q),l:_t("Elle se termine par un point d’interrogation")},{ok:!isNaN(d)&&d>new Date(),l:_t("Une date de clôture dans le futur")},{ok:dr.src.trim().length>=3,l:_t("Une source de résolution vérifiable")},{ok:dr.rules.trim().length>=30,l:_t("Des règles d’au moins 30 caractères")}];}
function crPreviewH(){const dr=S.ui.draft,p=+dr.p0,days=dr.date?Math.max(0,Math.round((new Date(dr.date+'T'+(dr.time||'21:00'))-new Date())/864e5)):null;return `<div class="prevcard"><div class="cat">${esc(_t(dr.cat))}</div><div class="q">${dr.q.trim()?esc(dr.q.trim()):`<span class="muted">${_t("Ta question apparaîtra ici")}</span>`}</div><div class="prevrow"><div><b class="num">${F.pct(p)}</b><small>${_t("chance Oui")}</small></div><div class="hbtns"><span class="btn b-yes-soft sm">${_t("Oui {0} ¢",[p])}</span><span class="btn b-no-soft sm">${_t("Non {0} ¢",[100-p])}</span></div></div><div class="sub">${days===null?_t("Choisis une date de clôture"):days===0?_t("Clôture aujourd’hui"):`${_t("Clôture dans {0} j",[days])}`}${dr.src.trim()?`${_t(", résolu selon {0}",[esc(dr.src.trim())])}`:''}</div></div>`;}
function crChecksH(){return crChecks(S.ui.draft).map(c=>`<div class="chk2${c.ok?' ok':''}"><span class="ck">${c.ok?ic('check',12,'#fff',3):''}</span>${c.l}</div>`).join('');}
function propRowH(pr,mine){const tot=pr.for+pr.against,pct=Math.round(pr.for/Math.max(1,pr.need)*100);const st=pr.status==='live'?`<a class="btn b-white sm" href="#marche-${pr.mid}">${_t("Voir le marché")}</a>`:mine?`<span class="xpc" data-prs="${pr.id}">${_t("En vote")}</span>`:(S.me.voted[pr.id]?`<span class="xpc">${_t("Tu as voté {0}",[S.me.voted[pr.id]==='for'?_t('pour'):_t('contre')])}</span>`:`<span class="hbtns"><button class="btn b-yes-soft sm" data-a="vote" data-id="${pr.id}" data-v="for">${_t("Pour")}</button><button class="btn b-no-soft sm" data-a="vote" data-id="${pr.id}" data-v="against">${_t("Contre")}</button></span>`);
 return `<div class="prop" data-prop="${pr.id}"><div class="pq"><span class="tag2">${_t(pr.cat)}</span><b>${esc(pr.q)}</b><small>${mine?_t("Ta proposition"):_t("Proposée par ")+esc(userOf(pr.by).n)}, <span data-prv="${pr.id}">${_t("{0} pour, {1} contre",[pr.for,pr.against])}</span>${pr.status==='live'?_t(", validée"):`${_t(", {0} votes pour la valider",[pr.need])}`}</small></div>${st}<div class="xpbar sm"><i data-prb="${pr.id}" style="width:${Math.min(100,pct)}%"></i></div></div>`;}
function vCreate(){const dr=S.ui.draft,tab=S.ui.crTab,mine=S.me.props||[];if(!dr.date){const d=new Date(Date.now()+30*864e5);dr.date=d.toISOString().slice(0,10);}const okAll=crChecks(dr).every(c=>c.ok)&&can('propose');
 const tabs=`<div class="tabs utabs">${[['form',_t("Nouveau pari")],['mine',`${_t("Mes propositions{0}",[mine.length?' ('+mine.length+')':''])}`],['vote',_t("À voter")]].map(([k,l])=>`<button class="${tab===k?'on':''}" data-a="cr-tab" data-v="${k}">${l}</button>`).join('')}</div>`;
 let body='';
 if(tab==='form')body=`${can('propose')?'':`<button class="lockrow on-bg w-full mb-4" data-a="lock" data-g="propose"><span class="row-c gap-3">${ic('lock',16,'#7A808C')}<span>${_t("Créer un pari se débloque au rang Or. Clique pour voir ce qu’il te manque.")}</span></span>${rk(3,0)}</button>`}<div class="g-dep"><form class="col" data-form="create" novalidate>
 <section class="pn pad step"><div class="step-h"><i>1</i><h3>${_t("La question")}</h3></div><div class="field"><label for="cq">${_t("Question, avec une réponse Oui ou Non")}</label><input id="cq" data-cr="q" maxlength="120" placeholder="${_t("Le PSG sera-t-il champion de France 2027 ?")}" value="${esc(dr.q)}" autocomplete="off"><span class="sub" data-crcount>${dr.q.length} / 120</span></div><div class="field"><label>${_t("Catégorie")}</label><div class="chips">${CATS.filter(c=>c!=='Tout').map(c=>`<button type="button" class="chip${dr.cat===c?' on':''}" data-a="cr-cat" data-v="${c}">${_t(c)}</button>`).join('')}</div></div></section>
 <section class="pn pad step"><div class="step-h"><i>2</i><h3>${_t("Clôture et résolution")}</h3></div><div class="row2"><div class="field"><label for="cd">${_t("Date de clôture")}</label><input id="cd" type="date" data-cr="date" value="${dr.date}" min="${today()}"></div><div class="field"><label for="ct">${_t("Heure")}</label><input id="ct" type="time" data-cr="time" value="${dr.time}"></div></div><div class="field"><label for="cs">${_t("Source de résolution")}</label><input id="cs" data-cr="src" placeholder="${_t("Site officiel de la Ligue 1")}" value="${esc(dr.src)}" autocomplete="off"></div><div class="field"><label for="crr">${_t("Règles de résolution")}</label><textarea id="crr" data-cr="rules" rows="4" placeholder="${_t("Ce marché se résout par Oui si…")}">${esc(dr.rules)}</textarea><button type="button" class="link self-start t-2" data-a="cr-rules">${_t("Rédiger les règles à partir de ma question")}</button></div></section>
 <section class="pn pad step"><div class="step-h"><i>3</i><h3>${_t("Cote de départ")}</h3></div><div class="field"><label for="cp">${_t("Chance de Oui au lancement :")} <b data-crp>${F.pct(dr.p0)}</b></label><input id="cp" type="range" min="5" max="95" step="1" value="${dr.p0}" data-cr="p0" class="range"></div><p class="sub">${_t("Elle bougera ensuite avec les mises des joueurs.")}</p></section>
 <section class="pn pad step"><div class="step-h"><i>4</i><h3>${_t("Publication")}</h3></div><label class="net on cur-def"><span class="rad"></span><span class="nn">${_t("<b>Envoyer au vote de la communauté</b>")}<small>${_t("Il suffit de 25 votes favorables pour le mettre en ligne. +50 XP s’il est validé.")}</small></span>${rk(3,0)}</label>${can('publish')?'':`<button type="button" class="net" data-a="lock" data-g="publish"><span class="rad"></span><span class="nn">${_t("<b>Publier directement, sans vote</b>")}<small>${_t("Réservé aux joueurs Immortel et Radiant.")}</small></span>${rk(7,0)}</button>`}<button class="btn b-ink lg full" type="submit" data-crsubmit${okAll?'':' disabled'}>${_t("Envoyer ma proposition")}</button></section></form>
 <aside class="col"><section class="pn pad" style="position:sticky;top:88px"><div class="sub mb-3">${_t("Aperçu dans la liste des marchés")}</div><div data-crprev>${crPreviewH()}</div><hr><div class="h2 t-3 mb-2">${_t("Avant d’envoyer")}</div><div data-crcheck>${crChecksH()}</div><hr><div class="h2 t-3 mb-2">${_t("Ce qui est refusé")}</div><p class="sub lh-p">${_t("Les questions sur des personnes privées, la violence ou la santé de quelqu’un, et celles dont le résultat ne peut pas être vérifié.")}</p></section></aside></div>`;
 else if(tab==='mine')body=`<section class="pn pad">${mine.length?mine.map(p=>propRowH(p,true)).join(''):`<div class="empty">${_t("Tu n’as encore rien proposé.")} <button class="link" data-a="cr-tab" data-v="form">${_t("Créer un pari")}</button></div>`}</section>`;
 else body=`<section class="pn pad"><div class="sub mb-2">${_t("Vote pour les marchés que tu veux voir en ligne. +2 XP par vote.")}</div>${COMM_PROPS.map(p=>propRowH(p,false)).join('')}</section>`;
 return `<div class="wrap"><div class="pagehead"><div><h1 class="ptitle">${_t("Créer un pari")}</h1><p class="plead">${_t("Pose une question avec une réponse claire, Oui ou Non. Si la communauté la valide, ton pari passe en ligne avec son propre chat.")}</p></div>${tabs}</div>${body}</div>`;}
function crRefresh(){const p=$('[data-crprev]');if(p){p.innerHTML=crPreviewH();fixText(p);}const c=$('[data-crcheck]');if(c){c.innerHTML=crChecksH();fixText(c);}const b=$('[data-crsubmit]');if(b)b.disabled=!(crChecks(S.ui.draft).every(x=>x.ok)&&can('propose'));const n=$('[data-crcount]');if(n)n.textContent=S.ui.draft.q.length+' / 120';const v=$('[data-crp]');if(v)v.textContent=S.ui.draft.p0+' %';}
document.addEventListener('input',e=>{const k=e.target.dataset&&e.target.dataset.cr;if(!k)return;S.ui.draft[k]=e.target.value;crRefresh();});
FORMS.create=()=>{const dr=S.ui.draft;if(!can('propose')){lockModal('propose');return;}if(!crChecks(dr).every(c=>c.ok)){toast({tone:'amber',icon:'info',title:_t("Il manque quelque chose"),text:_t("Vérifie la liste « Avant d’envoyer ».")});return;}
 if(SRV()){srvPropCreer(dr);return;}                              /* mode Compte : la proposition, ses votes et sa mise en ligne sont tenus par le serveur */
 const pr={id:'pr'+Date.now(),q:dr.q.trim(),cat:dr.cat,date:dr.date,time:dr.time,src:dr.src.trim(),rules:dr.rules.trim(),p0:+dr.p0,status:'vote',for:1,against:0,need:25,at:now()};S.me.props.unshift(pr);
 S.ui.draft={q:'',cat:dr.cat,date:'',time:'21:00',src:'',rules:'',p0:50};S.ui.crTab='mine';toast({tone:'blue',icon:'check',title:_t("Proposition envoyée au vote"),text:_t("Tu la retrouves dans Mes paris créés, sur l’accueil et sur ton profil.")});notif('plus',`${_t("Ta proposition « {0} » est en vote.",[shortOf(pr.q)])}`,'#creer');gainXP(10);render(true);save();};
function createMarketFromProposal(pr,announce){if(SRV())return MK[pr.mid];const id='perso-'+slugify(pr.q)+'-'+(hash(pr.id)%1000);pr.mid=id;if(MK[id])return MK[id];const d=new Date(pr.date+'T'+(pr.time||'21:00'));const days=Math.max(0,Math.round((d-new Date())/864e5));
 const m={id,cat:pr.cat,q:pr.q,short:shortOf(pr.q),p:pr.p0,d0:pr.p0,vol:250,close:days<=0?_t("Aujourd’hui"):_t("Dans ")+days+' j',closeLong:dateFr(pr.date,pr.time),days,people:12,msgs:0,heat:1.6,rules:pr.rules+(pr.src?` ${_t("Source : {0}.",[pr.src])}`:''),creator:'me',anchor:pr.p0,bets:[],online:9,hotUntil:now()+90000};
 for(let i=0;i<30;i++)m.bets.push({s:R()<m.p/100?1:0,a:Math.pow(R(),2.2),me:0});MARKETS.push(m);MK[id]=m;room('m:'+id).msgs.push(mkMsg({k:'evt',text:`${_t("Pari proposé par {0} et validé par la communauté.",[S.me.n])}`}));
 if(announce){toast({tone:'blue',icon:'check',title:_t("Ton pari est en ligne"),text:F.kv(m.short,'+'+F.xp(50)),href:'#marche-'+id,dur:6000});notif('check',`${_t("Ton pari « {0} » est en ligne.",[m.short])}`,'#marche-'+id);gainXP(50);confetti(40);}return m;}
Object.assign(ACT,{
 'cr-tab':a=>{S.ui.crTab=a.dataset.v;if((S.ui.route||'')!=='creer'){location.hash='#creer';return;}render(false);},
 'cr-cat':a=>{S.ui.draft.cat=a.dataset.v;$$('[data-a="cr-cat"]').forEach(b=>b.classList.toggle('on',b.dataset.v===a.dataset.v));crRefresh();},
 'cr-rules':()=>{const dr=S.ui.draft;const q=dr.q.trim()||'ta question';dr.rules=`${_t("Ce marché se résout par Oui si la réponse à la question « {0} » est oui au {1}, d’après {2}. Sinon, il se résout par Non.",[q.replace(/\s*\?$/,''),dateFr(dr.date,dr.time)||_t("jour de la clôture"),dr.src.trim()||'une source officielle'])}`;const t=$('#crr');if(t)t.value=dr.rules;crRefresh();},
 vote:(a,e)=>{const p=COMM_PROPS.find(x=>x.id===a.dataset.id);if(!p||S.me.voted[p.id])return;if(SRV()){srvPropVoter(p,a.dataset.v,e);return;}S.me.voted[p.id]=a.dataset.v;p[a.dataset.v==='for'?'for':'against']++;gainXP(2,e);render(false);save();}
});

/* ===================== Connexion et inscription ===================== */
const EMAIL_RE=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function authSide(){return `<aside class="auth-side"><div class="as-in"><div class="h2">${_t("Le marché qui se joue à plusieurs")}</div><div class="as-l">${[['chat',_t("Un chat pour chaque pari, et un chat global.")],['bolt',_t("Un pari éclair toutes les 45 secondes, en rotation ou en parallèle.")],['trophy',_t("Des rangs de Fer à Radiant, qui débloquent les fonctions.")],['wallet',_t("Dépôts en crypto, ou par carte, virement et PayPal avec le KYC.")]].map(([i,t])=>`<div class="as-r"><span>${ic(i,18,'#fff')}</span>${t}</div>`).join('')}</div><div class="as-emb">${[0,2,3,5,6,8].map(t=>emb(t,t===8?0:2)).join('')}</div></div></aside>`;}
function authShell(inner){return `<div class="wrap"><div class="auth"><div class="auth-main">${inner}${langRowH()}</div>${authSide()}</div></div>`;}
function authRedirect(){if(S.me.logged&&/^(connexion|inscription)$/.test(S.ui.route||'')){setTimeout(()=>location.replace(S.me.onboarded?'#accueil':'#bienvenue'),0);return true;}return false;}
function authThemeBtn(){return `<button class="thm au-thm" data-a="theme" aria-label="${_t("Changer de thème")}">${ic(isDark()?'sun':'moon',18)}</button>`;}
function vLogin(){if(authRedirect())return '';const m=S.ui.authMode,note=S.ui.authNote;S.ui.authNote='';
 return authShell(`<div class="auth-card"><h1>${_t("Se connecter")}</h1><p class="sub t-3">${_t("Content de te revoir.")}</p>${note?`<div class="limit over mt-4">${esc(note)}</div>`:''}
 <div class="seg w-full mt-5"><button class="${m==='mail'?'on':''} flex-1" data-a="auth-mode" data-v="mail">${_t("E-mail")}</button><button class="${m==='wallet'?'on':''} flex-1" data-a="auth-mode" data-v="wallet">${_t("Portefeuille crypto")}</button></div>
 ${m==='mail'?`<form class="col gap-4 mt-5" data-form="login" novalidate><div class="field"><label for="le">${_t("E-mail ou pseudo")}</label><input id="le" name="email" type="text" autocomplete="username" autocapitalize="none" spellcheck="false" value="${esc(S.ui.authEmail||'')}" placeholder="${_t("toi@exemple.fr")}"></div><div class="field"><label for="lp">${_t("Mot de passe")}</label><div class="pw"><input id="lp" name="pw" type="password" autocomplete="current-password" placeholder="${_t("8 caractères minimum")}"><button type="button" class="link" data-a="pw-toggle" data-for="lp">${_t("Afficher")}</button></div></div><button class="link self-start t-2" type="button" data-a="forgot">${_t("Mot de passe oublié ?")}</button><p class="err" data-autherr></p><button class="btn b-pri lg full" type="submit">${_t("Se connecter")}</button></form>`
 :`<div class="pickl mt-5">${[[_t("Portefeuille Ethereum du navigateur"),_t("Ethereum, Base, Arbitrum")],[_t("Portefeuille Solana"),'Solana'],[_t("Application mobile"),_t("Scanne un QR code avec ton portefeuille")]].map(([t,s2])=>`<button data-a="wallet" data-v="${t}" data-new=""><span><b>${t}</b><small class="muted d-block">${s2}</small></span>${ic('right',18)}</button>`).join('')}</div><p class="sub mt-3">${_t("Tu signes un message pour prouver que l’adresse t’appartient. Aucune transaction, aucun frais.")}</p>`}
 <div class="orl"><span>${_t("ou")}</span></div><button class="btn b-ghost lg full" data-a="demo-login">${_t("Utiliser le compte démo (User26, Or II)")}</button><p class="sub ta-c mt-3">${_t("Le compte démo reste dans ce navigateur : rien n’est envoyé, aucun argent réel.")}</p><p class="sub ta-c mt-5 t-2">${_t("Pas encore de compte ?")} <a class="link" href="#inscription">${_t("S’inscrire")}</a></p></div>`);}
function walletModal(){openModal(`<div class="md"><div class="md-h"><div><h3>${_t("S’inscrire avec un portefeuille")}</h3><p>${_t("Tu signes un message pour prouver que l’adresse t’appartient. Aucune transaction, aucun frais.")}</p>${demoHint(_t('Simulation : un compte de démonstration est créé dans ce navigateur.'))}</div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><div class="pickl">${[[_t("Portefeuille Ethereum du navigateur"),_t("Ethereum, Base, Arbitrum")],[_t("Portefeuille Solana"),'Solana'],[_t("Application mobile"),_t("Scanne un QR code avec ton portefeuille")]].map(([t,s2])=>`<button data-a="wallet" data-v="${t}" data-new="1"><span><b>${t}</b><small class="muted d-block">${s2}</small></span>${ic('right',18)}</button>`).join('')}</div><p class="sub mt-3">${_t("En continuant, tu confirmes avoir 18 ans ou plus et accepter les conditions d’utilisation.")}</p></div>`);}
function pwScore(p){let s=0;if(p.length>=8)s++;if(/[A-Z]/.test(p)&&/[a-z]/.test(p))s++;if(/\d/.test(p))s++;if(/[^A-Za-z0-9]/.test(p)||p.length>=12)s++;return s;}
const PW_L=[_t("Trop court"),_t("Faible"),_t("Moyen"),_t("Bon"),_t("Excellent")];
const takenNames=()=>[...USER_IDS.map(u=>userOf(u).n.toLowerCase()),'user26','dan.h','admin','wemoro'];
/* Confirmation d'e-mail activée côté serveur : le compte existe, il reste à cliquer sur le lien reçu. */
function attenteMailH(){const em=S.ui.authWait;return authShell(`<div class="auth-card"><h1>${_t("Vérifie ta boîte mail")}</h1><p class="sub t-3 lh-p mt-2">${_t("On t’a envoyé un lien de confirmation à {0}. Clique dessus pour activer ton compte, puis connecte-toi.",[`<b>${esc(em)}</b>`])}</p><p class="err" data-waiterr style="min-height:18px"></p><div class="col gap-3 mt-2"><a class="btn b-pri lg full" href="#connexion" data-a="auth-wait-done">${_t("J’ai confirmé, me connecter")}</a><button class="btn b-ghost lg full" data-a="auth-resend">${_t("Renvoyer l’e-mail")}</button></div></div>`);}
function vSignup(){if(authRedirect())return '';if(S.ui.authWait)return attenteMailH();return authShell(`<div class="auth-card"><h1>${_t("S’inscrire")}</h1><p class="sub t-3">${_t("Une minute, et tu commences au rang Fer I.")}</p>
 <form class="col gap-4 mt-5" data-form="signup" novalidate><div class="field"><label for="sn">${_t("Pseudo")}</label><input id="sn" name="pseudo" data-su="pseudo" maxlength="20" autocomplete="username" placeholder="${_t("ton.pseudo")}"><span class="sub" data-sun>${_t("3 à 20 caractères : lettres, chiffres, point ou tiret bas.")}</span></div>
 <div class="field"><label for="se">${_t("E-mail")}</label><input id="se" name="email" type="email" data-su="email" autocomplete="email" placeholder="${_t("toi@exemple.fr")}"><span class="sub" data-sue></span></div>
 <div class="field"><label for="sp">${_t("Mot de passe")}</label><div class="pw"><input id="sp" name="pw" type="password" data-su="pw" autocomplete="new-password" placeholder="${_t("8 caractères minimum")}"><button type="button" class="link" data-a="pw-toggle" data-for="sp">${_t("Afficher")}</button></div><div class="strength" data-sus><i></i><i></i><i></i><i></i></div><span class="sub" data-sul>${_t("Utilise au moins 8 caractères.")}</span></div>
 <div class="field"><label for="sr">${_t("Code de parrainage (facultatif)")}</label><input id="sr" name="ref" data-su="ref" maxlength="14" autocomplete="off" autocapitalize="characters" value="${esc(pendingRef())}" placeholder="LEA-7K3"><span class="sub">${pendingRef()?`${_t("Code détecté : {0} offerts à ton inscription.",[F.usd0(REF.BONUS)])}`:`${_t("Avec le code d’un ami, {0} offerts à ton inscription.",[F.usd0(REF.BONUS)])}`}</span></div>
 <label class="chk"><input type="checkbox" name="age"> ${_t("J’ai 18 ans ou plus")}</label><label class="chk"><input type="checkbox" name="cgu"> ${_t("J’accepte les conditions d’utilisation et la politique de confidentialité")}</label>
 <p class="err" data-signerr></p><button class="btn b-pri lg full" type="submit">${_t("S’inscrire")}</button></form>
 <div class="orl"><span>${_t("ou")}</span></div><button class="btn b-ghost lg full" data-a="wallet-modal">${_t("{0} S’inscrire avec un portefeuille crypto",[ic('wallet',16)])}</button><p class="sub ta-c mt-5 t-2">${_t("Déjà un compte ?")} <a class="link" href="#connexion">${_t("Se connecter")}</a></p></div>`);}
function pseudoMsg(v){if(!v)return ['',_t("3 à 20 caractères : lettres, chiffres, point ou tiret bas.")];if(!/^[A-Za-z0-9._]{3,20}$/.test(v))return ['bad',_t("3 à 20 caractères : lettres, chiffres, point ou tiret bas.")];if(takenNames().includes(v.toLowerCase()))return ['bad',_t("Ce pseudo est déjà pris.")];return ['ok',_t("Ce pseudo est disponible.")];}
document.addEventListener('input',e=>{const k=e.target.dataset&&e.target.dataset.su;if(!k)return;const v=e.target.value;
 if(k==='pseudo'){const [st,msg]=pseudoMsg(v.trim());const el=$('[data-sun]');if(el){el.textContent=msg;el.style.color=st==='bad'?'var(--nonT)':st==='ok'?'var(--oui)':'';}}
 if(k==='email'){const el=$('[data-sue]');if(el){el.textContent=v&&!EMAIL_RE.test(v)?_t("Adresse e-mail invalide."):'';el.style.color='var(--nonT)';}}
 if(k==='pw'){const sc=v?pwScore(v):0;$$('[data-sus] i').forEach((i,n)=>{i.style.background=n<sc?(sc<=1?'var(--text-3)':sc===2?'var(--text-2)':'var(--accent)'):'';});const l=$('[data-sul]');if(l)l.textContent=v?(v.length<8?_t("Trop court : 8 caractères minimum."):_t("Sécurité : ")+PW_L[sc].toLowerCase()+'.'):_t("Utilise au moins 8 caractères.");}});
function doLogin(msg){if(typeof rgLoginBlocked==='function'&&rgLoginBlocked())return;S.me.logged=true;save();if(typeof duelSeed==='function')duelSeed();if(typeof clanSeed==='function')clanSeed();if(typeof comboSeed==='function')comboSeed();const to=!S.me.onboarded?'#bienvenue':S.ui.after&&!/connexion|inscription/.test(S.ui.after)?S.ui.after:'#accueil';S.ui.after='';updateHeader();toast({tone:'blue',icon:'check',title:msg||`${_t("Content de te revoir, {0}",[S.me.n])}`,text:`${_t("{0}, solde {1}",[rankName(myRank().t,myRank().d),F.usd(S.me.balance)])}`});if(location.hash===to)render(true);else location.hash=to;}
/* Connexion : toujours auprès du serveur, avec l'e-mail ou le pseudo. Les comptes locaux ne servent qu'au mode démo. */
FORMS.login=f=>{const id=f.email.value.trim(),p=f.pw.value,err=f.querySelector('[data-autherr]');if(id.indexOf('@')>=0?!EMAIL_RE.test(id):!/^[A-Za-z0-9._]{3,20}$/.test(id)){err.textContent=_t("Entre ton e-mail ou ton pseudo.");return;}if(p.length<8){err.textContent=_t("Le mot de passe fait au moins 8 caractères.");return;}srvConnexion(f,id,p,err);};
FORMS.signup=f=>{const n=f.pseudo.value.trim(),e=f.email.value.trim(),p=f.pw.value,err=f.querySelector('[data-signerr]');const [st,msg]=pseudoMsg(n);
 if(st!=='ok'){err.textContent=msg;return;}if(!EMAIL_RE.test(e)){err.textContent=_t("Entre une adresse e-mail valide.");return;}if(p.length<8){err.textContent=_t("Le mot de passe doit faire au moins 8 caractères.");return;}if(!f.age.checked){err.textContent=_t("Wimoro est réservé aux personnes majeures.");return;}if(!f.cgu.checked){err.textContent=_t("Accepte les conditions pour continuer.");return;}
 srvInscription(f,{pseudo:n,email:e,motDePasse:p,ref:f.ref?f.ref.value.trim():'',lang:LANG},err);};   /* le compte est créé sur le serveur : plus de compte local fantôme */
/* Mot de passe oublié : un code à 6 chiffres part par e-mail (étape 1), puis code + nouveau mot de passe (étape 2). */
FORMS.forgot=f=>{const st=f.dataset.step||'1',err=f.querySelector('[data-ferr]'),btn=f.querySelector('[type=submit]');
 if(st==='1'){const em=f.email.value.trim();if(!EMAIL_RE.test(em)){err.textContent=_t("Entre une adresse e-mail valide.");return;}btn.disabled=true;err.textContent=_t("Envoi…");API.resetRequest(em).then(()=>forgotModal(2,em)).catch(e=>{err.textContent=errTxt(e);btn.disabled=false;});return;}
 if(!/^\d{6}$/.test(f.code.value.trim())){err.textContent=_t("Le code contient 6 chiffres.");return;}if(f.pw.value.length<8){err.textContent=_t("8 caractères minimum.");return;}
 btn.disabled=true;err.textContent=_t("Vérification en cours…");API.resetConfirm(f.dataset.email||'',f.code.value.trim(),f.pw.value).then(()=>srvRecharger('#accueil','motdepasse')).catch(e=>{err.textContent=errTxt(e);btn.disabled=false;});};
/* Arrivée par le lien de l'e-mail : la session de récupération est ouverte, il reste à choisir le nouveau mot de passe. */
function recupModal(){openModal(`<div class="md"><div class="md-h"><div><h3>${_t("Nouveau mot de passe")}</h3><p>${_t("Choisis un nouveau mot de passe pour ton compte.")}</p></div></div><form class="col gap-4" data-form="recup" novalidate><div class="field"><label for="rp">${_t("Nouveau mot de passe")}</label><input id="rp" name="pw" type="password" autofocus placeholder="${_t("8 caractères minimum")}"></div><p class="err" data-ferr></p><button class="btn b-ink lg full" type="submit">${_t("Changer mon mot de passe")}</button></form></div>`);}
FORMS.recup=f=>{const err=f.querySelector('[data-ferr]'),btn=f.querySelector('[type=submit]');if(f.pw.value.length<8){err.textContent=_t("8 caractères minimum.");return;}btn.disabled=true;API.updatePassword(f.pw.value).then(()=>srvRecharger('#accueil','motdepasse')).catch(e=>{err.textContent=errTxt(e);btn.disabled=false;});};
function forgotModal(step=1,email=''){openModal(`<div class="md"><div class="md-h"><div><h3>${step===1?_t("Mot de passe oublié"):_t("Vérifie tes e-mails")}</h3><p>${step===1?_t("On t’envoie un code pour choisir un nouveau mot de passe."):_t('Entre le code à 6 chiffres reçu par e-mail.')}</p></div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><form class="col gap-4" data-form="forgot" data-step="${step}" data-email="${esc(email)}" novalidate>${step===1?`<div class="field"><label for="fe">${_t("E-mail")}</label><input id="fe" name="email" type="email" autofocus value="${esc(email)}"></div>`:`<div class="field"><label for="fc">${_t("Code reçu à {0}",[esc(email)])}</label><input id="fc" name="code" inputmode="numeric" maxlength="6" autofocus placeholder="123456"></div><div class="field"><label for="fp">${_t("Nouveau mot de passe")}</label><input id="fp" name="pw" type="password" placeholder="${_t("8 caractères minimum")}"></div>`}<p class="err" data-ferr></p><button class="btn b-ink lg full" type="submit">${step===1?_t("Envoyer le code"):_t("Changer mon mot de passe")}</button></form></div>`);}
Object.assign(ACT,{
 'auth-mode':a=>{S.ui.authMode=a.dataset.v;if(a.dataset.go&&location.hash!==a.dataset.go){location.hash=a.dataset.go;return;}render(false);},
 'pw-toggle':a=>{const i=$('#'+a.dataset.for);if(!i)return;const show=i.type==='password';i.type=show?'text':'password';a.textContent=show?_t("Masquer"):_t("Afficher");},
 forgot:()=>forgotModal(1),
 'auth-wait-done':()=>{S.ui.authEmail=S.ui.authWait||'';S.ui.authWait='';},
 'auth-resend':a=>{a.disabled=true;API.resendConfirmation(S.ui.authWait).then(()=>toast({tone:'blue',icon:'send',force:true,title:_t("E-mail renvoyé")})).catch(e=>{const el=$('[data-waiterr]');if(el)el.textContent=errTxt(e);}).finally(()=>{a.disabled=false;});},
 wallet:a=>{const isNew=!!a.dataset.new;toast({icon:'wallet',title:_t("Signature demandée"),text:`${_t("Confirme dans « {0} ».",[a.dataset.v])}`,dur:1800});$$('[data-a="wallet"]').forEach(b=>b.disabled=true);a.classList.add('busy');setTimeout(()=>{closeModal();const all=AUTH.all(),wk=Object.keys(all).find(k=>k.startsWith('w:'));if(isNew||!wk){createAccount('joueur'+Math.floor(R()*9000+1000),'',null,{wallet:true});if(typeof refApplyAtSignup==='function')refApplyAtSignup(pendingRef());S.ui.ob=1;toast({tone:'blue',icon:'check',title:_t("Portefeuille connecté"),text:_t("Ton compte est créé. Encore 5 petites étapes.")});location.hash='#bienvenue';}else{enterAccount(all[wk]);doLogin(_t("Portefeuille connecté"));}},1600);},
 'wallet-modal':()=>walletModal(),
 'demo-login':()=>{enterAccount(DEMO_ACC);S.me.welcomed=true;doLogin(_t("Compte démo : User26"));},
 logout:()=>logout()
});

/* ===================== Accueil d’un nouveau joueur ===================== */
const OB_COLORS=['#2448FF','#F59A0B','#14161B','#13804F','#AE2139','#7350E3'];
const obKycLbl=p=>p==='kyc'?_t('Vérifier mon identité'):_t('Continuer en crypto uniquement');
function vOnboarding(){const s=S.ui.ob,me=S.me,dots=[1,2,3,4,5].map(i=>`<i class="${i<=s?'on':''}"></i>`).join('');let c='',next=_t("Continuer"),canNext=true,hideNext=false;
 if(s===1)c=`<div class="ob-av${avClass('me')}" style="background:${me.color}">${avInner('me',84)}</div><h1>${_t("Bienvenue sur Wimoro, {0}",[esc(me.n)])}</h1><p class="plead">${_t("Choisis ta couleur. Elle apparaîtra à côté de ton pseudo dans tous les chats.")}</p><div class="ob-sw">${OB_COLORS.map(col=>`<button class="${me.color===col?'on':''}" style="background:${col}" data-a="ob-color" data-v="${col}" aria-label="${_t("Couleur {0}",[col])}"></button>`).join('')}</div>`;
 else if(s===2){canNext=me.interests.length>0;c=`<h1>${_t("Qu’est-ce qui t’intéresse ?")}</h1><p class="plead">${_t("On mettra ces marchés en avant sur ton accueil. Choisis-en au moins un.")}</p><div class="chips jc-c mt-6">${CATS.filter(x=>x!=='Tout').map(x=>`<button class="chip lg${me.interests.includes(x)?' on':''}" data-a="ob-int" data-v="${x}">${_t(x)}</button>`).join('')}</div>`;}
 else if(s===3){/* C22 : deux choix sélectionnables, le bouton principal suit le choix ; une seule façon de reporter (choisir « Sans KYC ») */
  const pick=S.ui.kycPick||'crypto';hideNext=!me.kyc&&!!S.ui.kycOpen;next=me.kyc?_t('Continuer'):obKycLbl(pick);c=me.kyc?`${ic('shield',40,'#2448FF')}<h1>${_t("Identité vérifiée")}</h1><p class="plead">${_t("Carte, virement et PayPal sont débloqués pour tes dépôts et tes retraits. La crypto reste disponible.")}</p>`:S.ui.kycOpen?`<h1>${_t("Vérification d’identité (KYC)")}</h1>${demoHint(_t('Rien n’est envoyé ni conservé.'))}<div class="ta-s mt-4">${kycFormH('ob')}</div>`:`<h1>${_t("Vérifier ton identité ?")}</h1><p class="plead">${_t("Choisis une option. Tu pourras changer d’avis plus tard depuis ton profil.")}</p><div class="kopts ta-s mt-5" role="radiogroup" aria-label="${_t('Vérifier ton identité ?')}"><button class="kopt${pick==='kyc'?' on':''}" role="radio" aria-checked="${pick==='kyc'}" data-a="ob-kpick" data-v="kyc"><span class="kt"><i class="krad" aria-hidden="true"></i>${_t("<b>Avec KYC</b>")}<span class="tag">${_t("Recommandé")}</span></span><ul><li>${_t("Dépôts et retraits par carte, virement et PayPal")}</li><li>${_t("La crypto reste disponible")}</li><li>${_t("Vérification rapide")}</li></ul></button><button class="kopt${pick==='crypto'?' on':''}" role="radio" aria-checked="${pick==='crypto'}" data-a="ob-kpick" data-v="crypto"><span class="kt"><i class="krad" aria-hidden="true"></i>${_t("<b>Sans KYC</b>")}</span><ul><li>${_t("Dépôts et retraits en crypto uniquement")}</li><li>${_t("Les autres moyens restent visibles, grisés")}</li><li>${_t("Tu pourras faire le KYC quand tu veux")}</li></ul></button></div>`;}
 else if(s===4)c=`${emb(0,0,'xl')}<h1>${_t("Tu commences au rang Fer I")}</h1><p class="plead">${_t("Gagne de l’XP en pariant, en discutant et au pari éclair. Chaque rang débloque de nouvelles fonctions. Aucune limite de mise liée au rang : seule la liquidité du marché compte.")}</p><div class="ob-lad">${TIERS.map((T,i)=>`<span>${emb(i,0)}<small>${T.name}</small></span>`).join('')}</div><div class="limit mt-5 ta-s"><span>${_t("Pour passer <b>Bronze</b> : 300 XP et 3 paris réglés. Astuce : un pari éclair se règle en 45 secondes.")}</span></div>`;
 else{const claimed=me.xp>=100||me.obBonus;next=claimed?_t("Découvrir les marchés"):_t("Récupérer mes 100 XP");c=`<h1>${_t("Tes premières missions")}</h1><p class="plead">${_t("Chaque mission rapporte de l’XP. Tu les retrouves sur la page Ton rang.")}</p><div class="ob-mis">${me.missions.map(m=>`<div class="line"><span>${m.label}</span><span class="xpc">+${m.xp} XP</span></div>`).join('')}</div><div class="ob-gift${claimed?' done':''}">${ic('gift',22,claimed?'#13804F':'#2448FF')}<span><b>${claimed?_t("100 XP de bienvenue récupérés"):_t("100 XP de bienvenue")}</b><small>${claimed?_t("Tu es passé Fer II. Bravo !"):_t("Offerts pour ton arrivée.")}</small></span></div>${claimed?`<div class="hbtns jc-c mt-4"><a class="btn b-white" href="#depot" data-a="ob-done">${_t("{0} Faire mon premier dépôt",[ic('wallet',16)])}</a><a class="btn b-white" href="#eclair" data-a="ob-done">${_t("{0} Jouer un pari éclair",[ic('bolt',16)])}</a><a class="btn b-white" href="#clans" data-a="ob-done">${_t("{0} Découvrir les clans",[ic('shield',16)])}</a></div>`:''}`;}
 return `<div class="ob"><div class="pn ob-card"><div class="ob-dots" aria-label="${_t("Étape {0} sur 5",[s])}">${dots}</div><div class="ob-body">${c}</div><div class="ob-acts">${s>1?`<button class="btn b-ghost lg" data-a="ob-back">${_t('Retour')}</button>`:'<span></span>'}${hideNext?'<span></span>':`<button class="btn b-pri lg" data-a="ob-next"${canNext?'':' disabled'}>${next}</button>`}</div></div></div>`;}
Object.assign(ACT,{
 'ob-color':a=>{S.me.color=a.dataset.v;save();render(false);},
 'ob-int':a=>{const L=S.me.interests,v=a.dataset.v,i=L.indexOf(v);if(i>=0)L.splice(i,1);else L.push(v);save();render(false);},
 'ob-back':()=>{if(S.ui.ob===3&&S.ui.kycOpen){S.ui.kycOpen=false;render(false);return;}S.ui.ob=Math.max(1,S.ui.ob-1);render(false);},
 'ob-kpick':a=>{S.ui.kycPick=a.dataset.v;$$('.kopt[data-a="ob-kpick"]').forEach(b=>{const on=b===a;b.classList.toggle('on',on);b.setAttribute('aria-checked',on);});const n=$('.ob-acts [data-a="ob-next"]');if(n){n.textContent=obKycLbl(S.ui.kycPick);fixText(n);}},
 'ob-kyc':a=>{S.ui.kycOpen=a.dataset.v==='1';if(S.ui.kycOpen)S.ui.kycd={doc:false};render(false);},
 'ob-next':(a,e)=>{const me=S.me;if(S.ui.ob===3&&!me.kyc&&!S.ui.kycOpen&&(S.ui.kycPick||'crypto')==='kyc'){S.ui.kycOpen=true;S.ui.kycd={doc:false};render(false);return;}S.ui.kycOpen=false;if(S.ui.ob<5){S.ui.ob++;render(false);return;}if(!(me.xp>=100||me.obBonus)){if(SRV()){a.disabled=true;srvOnboarding({bonus:true},e).then(()=>setTimeout(()=>render(false),900));return;}me.obBonus=true;gainXP(100,e);setTimeout(()=>render(false),900);return;}if(SRV())srvOnboarding({done:true});me.onboarded=true;if(me.interests.length)S.ui.cat='Pour toi';save();location.hash='#accueil';},
 'ob-done':()=>{if(SRV())srvOnboarding({done:true});S.me.onboarded=true;if(S.me.interests.length)S.ui.cat='Pour toi';save();}
});

/* ===================== Routes ajoutées ===================== */
Object.assign(VIEWS,{creer:vCreate,connexion:vLogin,inscription:vSignup,bienvenue:vOnboarding});

/* ===================== Gains en vert, pertes en rouge ===================== */
const plc=v=>v>0.004?'pl-up':v<-0.004?'pl-dn':'';
const fmtPct=v=>bidi((v>=-0.05?'+':'−')+plain(F.d1(Math.abs(v)))+(SYMB?'%':' %'));
/* C14 : le bouton de vente dit ce que tu reçois et le résultat de la vente */
const sellLbl=c=>c.sh>0&&Math.abs(c.pnl)>=0.005?_t('Vendre · tu reçois {0} ({1})',[F.usd(c.pro),F.signed(c.pnl)]):_t('Vendre · tu reçois {0}',[F.usd(c.pro)]);
function sellCalcH(ctx,c){const st=tState(ctx),p=posOf(st.m,st.side)||{avg:c.price},has=c.sh>0&&Math.abs(c.pnl)>=0.005,g=c.pnl>=-0.004,cost=c.sh*p.avg/100,pct=cost>0?c.pnl/cost*100:0;
 return `<div class="calc"><div class="line"><span>${_t("Prix moyen de vente")}</span><b data-c="price">${F.c1(c.price)}</b></div><div class="line"><span>${_t("Ton prix moyen d’achat")}</span><b>${F.c1(p.avg)}</b></div><div class="line"><span>${_t("Impact sur le prix")}</span><b data-c="imp">${F.imp(-c.impact)}</b></div><div class="line"><span>${_t("Tu reçois (sans frais)")}</span><b data-c="pro">${F.usd(c.pro)}</b></div></div>
 <div class="plbox${has?(g?' is-gain':' is-loss'):''}" data-c="plbox"><span data-c="pll">${!has?_t("Résultat de la vente"):g?_t("Plus-value sur ces parts"):_t("Moins-value sur ces parts")}</span><span class="plv"><b class="num" data-c="pnl">${F.signed(has?c.pnl:0)}</b><small data-c="plp">${has?fmtPct(pct):''}</small></span></div>
 <button class="btn ${!has?'b-ink':g?'b-gain':'b-loss'} lg full" data-a="sell" data-ctx="${ctx}"${c.ok?'':' disabled'} data-c="btn">${sellLbl(c)}</button>
 <p class="note">${_t("Vendre est gratuit : aucun frais à la sortie. Le résultat tient compte de l’impact de ta vente sur le prix et bouge en direct.")}</p>`;}
function sellSync(box,c){const st=tState(box.dataset.tcalc),p=posOf(st.m,st.side);if(!p)return;const has=c.sh>0&&Math.abs(c.pnl)>=0.005,g=c.pnl>=-0.004,cost=c.sh*p.avg/100,pct=cost>0?c.pnl/cost*100:0,q=k=>box.querySelector(`[data-c="${k}"]`);
 const pb=q('plbox');if(pb){pb.classList.toggle('is-gain',has&&g);pb.classList.toggle('is-loss',has&&!g);}
 const l=q('pll');if(l)l.textContent=!has?_t("Résultat de la vente"):g?_t("Plus-value sur ces parts"):_t("Moins-value sur ces parts");
 const v=q('pnl');if(v)v.textContent=F.signed(has?c.pnl:0);const pp=q('plp');if(pp)pp.textContent=has?fmtPct(pct):'';
 const b=q('btn');if(b){b.textContent=sellLbl(c);b.classList.toggle('b-gain',has&&g);b.classList.toggle('b-loss',has&&!g);b.classList.toggle('b-ink',!has);b.disabled=!c.ok;}}

/* ===================== Graphique façon trading : courbe ou bougies ===================== */
const CTI={courbe:'<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 17l5-6 4 3 8-9"/></svg>',bougies:'<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M7 3v4M7 17v4M17 3v3M17 15v6"/><rect x="4.5" y="7" width="5" height="10" rx="1"/><rect x="14.5" y="6" width="5" height="9" rx="1"/></svg>'};
const ctype=()=>S.me.ctype==='bougies'?'bougies':'courbe';
function ctypeSeg(){const t=ctype();return `<div class="seg ctype" role="group" aria-label="${_t("Type de graphique")}">${[['courbe',_t("Courbe")],['bougies',_t("Bougies")]].map(([k,l])=>`<button class="${t===k?'on':''}" data-a="ctype" data-v="${k}" aria-pressed="${t===k}">${CTI[k]}${l}</button>`).join('')}</div>`;}
const CDUR={'1 h':_t('2 min 30'),'6 h':_t('15 min'),'1 j':_t('1 h'),'1 sem.':_t('7 h'),'Tout':_t('6 jours')};
function cdurH(where){if(ctype()!=='bougies')return '';return `<i class="cu"></i>${_t("Hausse")}<i class="cd"></i>${_t("Baisse")}<span class="sep"></span>${_t("1 bougie = {0}",[where==='flash'?'2 s':CDUR[S.ui.tf]])}`;}
function chartToolsH(id){return `<div class="chtools">${ctypeSeg()}<span class="cdur" data-cdur="${id}">${cdurH(id)}</span><button class="btn b-ink sm pro-open" data-a="pro-open" data-m="${id}">${_t("{0} Mode Pro",[ic('expand',15)])}</button><div class="ohlc" data-ohlc="${id}">${ohlcH(id)}</div></div>`;}
const TSPAN={'1 h':36e5,'6 h':216e5,'1 j':864e5,'1 sem.':6048e5,'Tout':1296e7};
function chartData(m){const t=ctype(),a=series(m,S.ui.tf),r=rng(hash(m.id+S.ui.tf+'c')),n=24,per=a.length/n,C=[];
 let prev=a[0];for(let k=0;k<n;k++){const base=a[(k+1)*per-1],o=prev,c=k===n-1?m.p:clamp(base+(r()-.5)*2.6,1,99),h=Math.min(99.5,Math.max(o,c)+.2+r()*1.1),l=Math.max(.5,Math.min(o,c)-.2-r()*1.1);C.push({o,c,h,l,v:.35+r()*.65+Math.min(1.6,Math.abs(c-o)*.45)});prev=c;}
 const lo=t==='bougies'?Math.min(...C.map(c=>c.l)):Math.min(...a),hi=t==='bougies'?Math.max(...C.map(c=>c.h)):Math.max(...a);
 let mn=Math.max(0,Math.floor((lo-3)/10)*10),mx=Math.min(100,Math.ceil((hi+3)/10)*10);if(mx-mn<20)mx=Math.min(100,mn+20);if(mx-mn<20)mn=Math.max(0,mx-20);
 return {t,a,C,mn,mx};}
const CHD={};
function chartInner(m){const d=chartData(m),{t,a,C,mn,mx}=d,W=800,H=240,y=v=>H-(v-mn)/(mx-mn)*H,n=C.length,sw=W/n,bw=sw*.56,vmax=Math.max(...C.map(c=>c.v)),VH=H*.16;CHD[m.id]=d;
 let g='',lab='',vol='',body='';
 for(let v=mn;v<=mx;v+=10){g+=`<line class="gl" x1="0" x2="${W}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/>`;lab+=`<span class="ylab" style="top:${(y(v)/H*100).toFixed(2)}%">${F.pct(v)}</span>`;}
 C.forEach((c,k)=>{const cx=sw*(k+.5),cl=c.c>=c.o?'up':'dn',vh=c.v/vmax*VH;vol+=`<rect class="vo ${t==='bougies'?cl:'nt'}" x="${(cx-bw/2).toFixed(1)}" y="${(H-vh).toFixed(1)}" width="${bw.toFixed(1)}" height="${vh.toFixed(1)}"/>`;
  if(t==='bougies'){const yt=y(Math.max(c.o,c.c)),yb=y(Math.min(c.o,c.c));body+=`<line class="wk ${cl}" x1="${cx.toFixed(1)}" x2="${cx.toFixed(1)}" y1="${y(c.h).toFixed(1)}" y2="${y(c.l).toFixed(1)}"/><rect class="bd ${cl}" x="${(cx-bw/2).toFixed(1)}" y="${yt.toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(1.6,yb-yt).toFixed(1)}"/>`;}});
 if(t!=='bougies'){const x=i=>i/(a.length-1)*W,p=a.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join('');body=`<path class="ar" d="${p} L${W} ${H} L0 ${H}Z"/><path class="ln" d="${p}"/>`;}
 const last=C[n-1],lc=t==='bougies'?(last.c>=last.o?'up':'dn'):'ln',yp=(y(m.p)/H*100).toFixed(2),per=a.length/n;
 const pins=[[16,.04],[42,.09],[63,.16]].map(([i,k])=>{const ci=Math.floor(i/per),left=t==='bougies'?(ci+.5)/n*100:i/(a.length-1)*100,top=t==='bougies'?y(C[ci].h):y(a[i]);return `<button class="pin" data-a="pin" style="left:${left.toFixed(2)}%;top:${(top/H*100).toFixed(2)}%" aria-label="${_t("Voir les messages de ce moment")}">${ic('chat',11,'#fff',2.4)} ${Math.max(3,Math.round(m.msgs*k))}</button>`;}).join('');
 return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">${g}${vol}${body}<line class="cur ${lc}" x1="0" x2="${W}" y1="${y(m.p).toFixed(1)}" y2="${y(m.p).toFixed(1)}"/></svg>${lab}<span class="ptag ${lc}" style="top:${yp}%">${F.pct(m.p)}</span>${pins}${t==='bougies'?'':`<i class="dot" style="left:100%;top:${yp}%"></i>`}`;}
function tfLabel(t){const d=new Date(t);if(S.ui.tf==='Tout')return d.toLocaleDateString(LOC,{day:'numeric',month:'short'});if(S.ui.tf==='1 sem.')return d.toLocaleDateString(LOC,{weekday:'short',day:'numeric'});return hhmm(t);}
function xlabs(tf){const sp=TSPAN[tf]||TSPAN['1 j'],n=now();return [0,.25,.5,.75].map(f=>tfLabel(n-sp*(1-f))).concat(_t("Maintenant"));}
function tfTime(f,live){if(live)return _t("Maintenant");const t=now()-TSPAN[S.ui.tf]*(1-f),d=new Date(t);if(S.ui.tf==='Tout')return d.toLocaleDateString(LOC,{day:'numeric',month:'short'});if(S.ui.tf==='1 sem.')return d.toLocaleDateString(LOC,{weekday:'short'})+' '+hhmm(t);return hhmm(t);}
function ohlcH(id,k){const m=MK[id];if(!m)return '';const {t,a,C}=chartData(m);
 if(t==='bougies'){const i=k===undefined?C.length-1:k,c=C[i],ch=c.c-c.o,cl=ch>=0?'pl-up':'pl-dn';return `<span class="ot">${i===C.length-1?_t("Bougie en cours"):tfTime((i+1)/C.length)}</span><span>${_t("Ouv. <b>{0}</b>",[F.pct(c.o)])}</span><span>${_t("Haut <b>{0}</b>",[F.pct(c.h)])}</span><span>${_t("Bas <b>{0}</b>",[F.pct(c.l)])}</span><span>${_t("Clôt.")} <b class="${cl}">${F.pct(c.c)}</b></span><b class="${cl}">${F.pts(ch)}</b>`;}
 const i=k===undefined?a.length-1:k,v=a[i];return `<span class="ot">${tfTime(i/(a.length-1),i===a.length-1)}</span><span>${_t("Oui <b>{0}</b>",[F.pct(v)])}</span>`;}
let XH=null;
function drawXH(el){const id=el.dataset.chart,d=CHD[id];if(!d||!XH||XH.id!==id)return;let o=el.querySelector('.xh');if(!o){o=document.createElement('div');o.className='xh';el.appendChild(o);}
 const {t,a,C,mn,mx}=d,Y=v=>(1-(v-mn)/(mx-mn))*100;let fx,v,k,lbl;
 if(t==='bougies'){k=clamp(Math.floor(XH.fx*C.length),0,C.length-1);fx=(k+.5)/C.length;v=C[k].c;lbl=k===C.length-1?_t("En cours"):tfTime((k+1)/C.length);}else{k=Math.round(XH.fx*(a.length-1));fx=k/(a.length-1);v=a[k];lbl=tfTime(fx,k===a.length-1);}
 o.innerHTML=`<i class="vx" style="left:${(fx*100).toFixed(2)}%"></i><i class="hy" style="top:${Y(v).toFixed(2)}%"></i><span class="yt" style="top:${Y(v).toFixed(2)}%">${F.pct(v)}</span><span class="xt" style="left:${(fx*100).toFixed(2)}%">${lbl}</span>${t==='bougies'?'':`<i class="hd" style="left:${(fx*100).toFixed(2)}%;top:${Y(v).toFixed(2)}%"></i>`}`;
 const lg=$(`[data-ohlc="${id}"]`);if(lg)lg.innerHTML=ohlcH(id,k);}
function clearXH(){if(!XH)return;const id=XH.id;XH=null;$$('.chart .xh').forEach(x=>x.remove());const lg=$(`[data-ohlc="${id}"]`);if(lg)lg.innerHTML=ohlcH(id);}
/* C12 : le réticule suit la souris comme avant, et maintenant le doigt (pointer events). Sur le graphique, touch-action:pan-y
   laisse le défilement vertical à la page ; un glissement horizontal déplace le réticule, qui reste affiché un instant après le lever du doigt. */
let xhT=0;
function xhAt(e){const el=e.target&&e.target.closest?e.target.closest('.chart[data-chart]'):null;if(!el){clearXH();return;}clearTimeout(xhT);const r=el.getBoundingClientRect();XH={id:el.dataset.chart,fx:clamp((e.clientX-r.left)/r.width,0,.9999)};drawXH(el);}
const xhEnd=e=>{if(e.pointerType!=='mouse'&&XH){clearTimeout(xhT);xhT=setTimeout(clearXH,1800);}};
document.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||XH)xhAt(e);},{passive:true});
document.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')xhAt(e);},{passive:true});
document.addEventListener('pointerup',xhEnd,{passive:true});document.addEventListener('pointercancel',xhEnd,{passive:true});
document.addEventListener('mouseout',e=>{if(!e.relatedTarget)clearXH();});
function refreshCharts(){const vh=innerHeight;$$('[data-chart]').forEach(el=>{const m=MK[el.dataset.chart];if(!m)return;const r=el.getBoundingClientRect();if(!r.width||r.bottom<-120||r.top>vh+120)return;el.innerHTML=chartInner(m);if(XH&&XH.id===el.dataset.chart)drawXH(el);});$$('[data-ohlc]').forEach(lg=>{if(!XH||XH.id!==lg.dataset.ohlc)lg.innerHTML=ohlcH(lg.dataset.ohlc);});}
ACT.ctype=a=>{S.me.ctype=a.dataset.v==='bougies'?'bougies':'courbe';save();$$('[data-a="ctype"]').forEach(b=>{const on=b.dataset.v===S.me.ctype;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));});$$('[data-cdur]').forEach(e=>e.innerHTML=cdurH(e.dataset.cdur));refreshCharts();updateFlash(true);if(typeof bzRefresh==='function')bzRefresh(true);if(typeof serieRefresh==='function')serieRefresh(true);};

