const PRIV=[['public',_t("Profil public"),_t("Tout le monde peut voir ton profil, ton rang et tes badges.")],['showpos',_t("Afficher mes positions"),_t("Les autres joueurs voient tes positions ouvertes.")],['dms',_t("Messages privés de tous"),_t("Les joueurs que tu ne suis pas peuvent t’écrire.")]];
