function pwModal(){openModal(`<div class="md"><div class="md-h"><div><h3>${_t("Changer le mot de passe")}</h3><p>${_t("8 caractères minimum. Mélange lettres, chiffres et symboles.")}</p></div><button class="x" data-a="close" aria-label="${_t("Fermer")}">${ic('x')}</button></div><form class="col gap-4" data-form="pwchange" novalidate><div class="field"><label for="pw0">${_t("Mot de passe actuel")}</label><input id="pw0" name="cur" type="password" autocomplete="current-password" autofocus></div><div class="field"><label for="pw1">${_t("Nouveau mot de passe")}</label><input id="pw1" name="pw" type="password" data-su="pw" autocomplete="new-password"><div class="strength" data-sus><i></i><i></i><i></i><i></i></div><span class="sub" data-sul>${_t("Utilise au moins 8 caractères.")}</span></div><div class="field"><label for="pw2">${_t("Confirme le nouveau mot de passe")}</label><input id="pw2" name="pw2" type="password" autocomplete="new-password"></div><p class="err" data-pwerr></p><button class="btn b-ink lg full" type="submit">${_t("Changer le mot de passe")}</button></form></div>`);}
FORMS.pwchange=f=>{const err=f.querySelector('[data-pwerr]');if(f.cur.value.length<8){err.textContent=_t("Ton mot de passe actuel fait au moins 8 caractères.");return;}if(f.pw.value.length<8){err.textContent=_t("Le nouveau mot de passe doit faire au moins 8 caractères.");return;}if(f.pw.value!==f.pw2.value){err.textContent=_t("Les deux mots de passe ne sont pas identiques.");return;}if(f.pw.value===f.cur.value){err.textContent=_t("Choisis un mot de passe différent de l’actuel.");return;}if(SRV()){const b=f.querySelector('[type=submit]');if(b)b.disabled=true;err.textContent=_t("Vérification en cours…");API.signIn(API.email,f.cur.value).then(()=>API.updatePassword(f.pw.value)).then(()=>{closeModal();toast({tone:'green',icon:'check',title:_t("Mot de passe changé"),text:_t("Utilise-le à ta prochaine connexion.")});}).catch(e=>{err.textContent=e.code==='identifiants'?_t("Mot de passe actuel incorrect."):errTxt(e);if(b)b.disabled=false;});return;}
 const rec=accountOfMe();if(rec&&rec.ph&&rec.ph!==pwHash(f.cur.value,rec.key)){err.textContent=_t("Mot de passe actuel incorrect.");return;}if(rec){rec.ph=pwHash(f.pw.value,rec.key);AUTH.set(rec.key,rec);}closeModal();toast({tone:'green',icon:'check',title:_t("Mot de passe changé"),text:_t("Utilise-le à ta prochaine connexion.")});notif('shield',_t('Ton mot de passe a été changé.'),'#modifier');};
FORMS.profile=()=>{const p=S.ui.pe;if(!p)return;const n=p.n.trim(),[st,msg]=peNameMsg(n);if(st==='bad'){toast({tone:'amber',icon:'info',title:_t("Pseudo invalide"),text:msg});const i=$('#pen');if(i)i.focus();return;}if(p.email.trim()&&!EMAIL_RE.test(p.email.trim())){toast({tone:'amber',icon:'info',title:_t("E-mail invalide"),text:_t("Vérifie ton adresse e-mail.")});const i=$('#pee');if(i)i.focus();return;}
 /* mode serveur : le pseudo (unique) et le profil sont validés par le serveur avant d'être appliqués ici */
 if(SRV()&&!p.srvOk){const im=String(p.photo||'').indexOf('data:')===0;if(im)p.photo=S.me.photo||'';p.email=S.me.email;p.wallet=S.me.wallet;srvProfil({n,bio:p.bio.trim(),color:p.color,photo:p.photo||'',interests:p.interests,pub:!!(p.prefs&&p.prefs.public)}).then(()=>{p.srvOk=true;FORMS.profile();if(im)toast({tone:'amber',icon:'info',force:true,title:_t("Photo importée non enregistrée"),text:_t("Pour l’instant, les comptes utilisent les avatars de la galerie.")});}).catch(srvErreur);return;}
 const me=S.me,renamed=n!==me.n;me.n=n;me.photo=p.photo||'';me.color=p.color;me.bio=p.bio.trim();me.interests=p.interests.slice();me.email=p.email.trim();me.wallet=p.wallet;me.prefs=Object.assign({},p.prefs);if(!me.interests.length&&S.ui.cat==='Pour toi')S.ui.cat='Tout';
 const rec=accountOfMe();if(rec&&!rec.demo){rec.pseudo=me.n;rec.email=me.email;AUTH.set(rec.key,rec);}S.ui.pe=null;updateHeader();save();toast({tone:'green',icon:'check',title:_t("Profil mis à jour"),text:renamed?`${_t("Tu t’appelles maintenant {0}.",[n])}`:_t("Tes changements sont enregistrés.")});notif('user',_t('Ton profil a été mis à jour.'),'#profil');location.hash='#profil';};
