function homeTabs(){const base=S.me.interests.length?['Pour toi',...CATS]:CATS.slice();if((S.me.props||[]).length){const i=base.indexOf('Tout');base.splice(i+1,0,'Mes paris créés');}else if(S.ui.cat==='Mes paris créés')S.ui.cat='Tout';return base;}
function voteRowH(pr){const pct=Math.min(100,pr.for/pr.need*100);return `<div class="row vrow" data-href="#creer"><div class="qcell"><div class="cat">${_t(pr.cat)}<span class="ctag vote">${_t("En vote")}</span></div><a class="q" href="#creer" data-a="cr-tab" data-v="mine">${esc(pr.q)}</a></div><div class="pv"><div class="num">${F.pct(pr.p0)}</div><div class="delta">${_t("au départ")}</div></div><div class="tr"><div class="vbar"><i data-prb="${pr.id}" style="width:${pct}%"></i></div><small data-prv="${pr.id}">${_t("{0} pour, {1} contre",[pr.for,pr.against])}</small></div><div class="vol"><div class="v" data-prc="${pr.id}">${pr.for} / ${pr.need}</div><div class="c">${_t("votes")}</div></div><div class="acts"><a class="btn b-ghost sm" href="#creer" data-a="cr-tab" data-v="mine">${_t("Suivre le vote")}</a></div></div>`;}
function myBoardH(){const P=S.me.props||[];const live=P.filter(p=>p.status==='live'&&MK[p.mid]).map(p=>MK[p.mid]),vote=P.filter(p=>p.status==='vote');if(!live.length&&!vote.length)return `<div class="empty">${_t("Tu n’as pas encore créé de pari.")} <a class="link" href="#creer" data-a="cr-tab" data-v="form">${_t("Créer un pari")}</a></div>`;
 return `<div class="hd"><span>${_t("Pari")}</span><span>${_t("Chance Oui")}</span><span>${_t("Volume")}</span><span>${_t("Total")}</span><span></span></div>`+live.map(rowH).join('')+vote.map(voteRowH).join('');}
function myBetsH(){const L=S.me.props||[];if(!L.length)return `<div class="empty">${_t("Tu n’as pas encore créé de pari.")} <a class="link" href="#creer" data-a="cr-tab" data-v="form">${_t("Créer un pari")}</a></div>`;
 return `<div class="p-1-5-3">${L.map(pr=>{const m=pr.status==='live'?MK[pr.mid]:null;if(m)return `<a class="act mybet" href="#marche-${m.id}"><span><span class="ctag">${_t("En ligne")}</span>${esc(m.q)}<small class="d-block mt-1">${_t("{0}, {1} participants, volume {2}",[_t(m.cat),F.int(m.people),F.compact(m.vol)])}</small></span><b class="num t-4" data-mp="${m.id}">${F.pct(m.p)}</b></a>`;
  return `<a class="act mybet" href="#creer" data-a="cr-tab" data-v="mine"><span><span class="ctag vote">${_t("En vote")}</span>${esc(pr.q)}<small class="d-block mt-1" data-prv="${pr.id}">${_t("{0} pour, {1} contre",[pr.for,pr.against])}</small></span><b class="num t-3 nowrap" data-prc="${pr.id}">${pr.for} / ${pr.need}</b></a>`;}).join('')}</div>`;}
function refreshMine(){const r=S.ui.route||'';if(r==='accueil'){const b=$('#board');if(b){b.innerHTML=boardH();fixText(b);mountTrails(b);}const t=$('.filters .tabs');if(t&&!t.querySelector('[data-v="Mes paris créés"]')&&(S.me.props||[]).length)render(false);}if(r==='profil'&&S.ui.ptab==='mine')render(false);if(r==='creer')render(false);}
function catchUpVotes(){let n=0;for(const pr of S.me.props||[]){if(pr.status!=='vote')continue;const g=Math.floor((now()-(pr.tick||pr.at||now()))/1500);if(g>0){pr.for=Math.min(pr.need,pr.for+g);pr.tick=now();}if(pr.for>=pr.need){pr.status='live';createMarketFromProposal(pr,true);n++;}}if(n){refreshMine();save();}}
function voteTick(){for(const pr of S.me.props||[]){if(pr.status!=='vote')continue;if(R()<.92)pr.for+=1+Math.floor(R()*3);if(R()<.18)pr.against++;pr.tick=now();
 $$(`[data-prv="${pr.id}"]`).forEach(e=>e.textContent=`${_t("{0} pour, {1} contre",[pr.for,pr.against])}`);$$(`[data-prb="${pr.id}"]`).forEach(e=>e.style.width=Math.min(100,pr.for/pr.need*100)+'%');$$(`[data-prc="${pr.id}"]`).forEach(e=>e.textContent=`${Math.min(pr.for,pr.need)} / ${pr.need}`);
 if(pr.for>=pr.need){pr.for=pr.need;pr.status='live';createMarketFromProposal(pr,true);refreshMine();}save();}}

