function friendBtnH(u,sm){const c=sm?' sm':'';if(friendsOf().includes(u))return `<button class="btn b-soft${c}" data-a="fr-menu" data-u="${u}">${_t("{0} Amis",[ic('check',15)])}</button>`;if(fOut().includes(u))return `<button class="btn b-white${c}" data-a="fr-cancel" data-u="${u}">${_t("Demande envoyée")}</button>`;if(fIn().includes(u))return `<button class="btn b-ink${c}" data-a="fr-accept" data-u="${u}">${_t("{0} Accepter",[ic('check',15,'#fff')])}</button>`;return `<button class="btn b-ink${c}" data-a="fr-add" data-u="${u}">${_t("{0} Ajouter en ami",[ic('plus',15,'#fff')])}</button>`;}
